message.content:
{
  "description": "The creature is shown in right-facing profile standing on a plain light background. It has the overall body shape and fur of a large quadrupedal mammal, with a bear-like head and paws, but its back, neck, sides, belly and most of its legs are covered by a highly glossy, dark brown segmented exoskeleton made of overlapping hard plates. The head is furry with a light tan muzzle and dark nose, and bears a smooth, shiny black cap-like plate on its crown from which a single large curved horn projects. The four thick legs end in broad furry feet with claws, and a small pointed segmented tail is visible at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a bear's head with dense brown fur, lighter tan fur on the muzzle and around the eyes, a large black nose at the tip of the snout, small dark eyes, and a closed mouth seen in profile facing right; located at the front end of the body on top of the plated neck"
    ,
      "where": "front of body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "a single large, glossy black, sharply curved horn with two small pointed tines on its front edge near the tip, arising from the center of the shiny head plate and curving up and backward",
      "where": "on top of the head, centered on the glossy head plate"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur, protruding outward",
      "where": "on top of the head on either side of the horn base, just above the edges of the head plate"
    },
    {
      "part": "legs",
      "looks_like": "four thick, pillar-like legs covered for most of their length by glossy dark brown overlapping segmented plates with visible sutures; the plates form rings around the upper legs and shingled scales on the lower legs, with small spiny projections on the front of the forelegs",
      "where": "under the body, two forelegs beneath the chest/neck and two hindlegs beneath the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws covered in shaggy brown fur with five long, curved, light-colored claws on each foot, the fur and claws clearly visible where the plated leg covering ends",
      "where": "at the bottom end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a small, short, pointed tail made of overlapping dark glossy segments that taper to a sharp tip, with a slightly spiky underside",
      "where": "at the rear of the body, tucked under the plated rump, pointing down and slightly back"
    },
    {
      "part": "plates",
      "looks_like": "an extensive glossy exoskeleton or shell of dark brown to black overlapping hard plates covering the dorsal back, sides, neck, belly and legs; the back plates are large, smooth and highly reflective with a row of small circular holes along the lower edge of the mid-back plates, the neck has narrower ring-like plates, and the leg plates are thick and segmented",
      "where": "covering the entire trunk from neck to rump, wrapping around the sides and belly, and sheathing most of each leg, plus a smooth cap-like plate on the head"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "rhinoceros beetle", "pill bug"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
